import {autoLayoutCommand,removeAutoLayoutCommand,gridMetadataCommand,constraintCommand,sizingCommand} from './layout-service.js';
export function renderLayoutPanel({api,content,esc}){
  const node=api.selected,style=node?.getStyle()||{},metadata=api.projectState.getLayoutMetadata()?.[node?.get('formaNodeId')]||{};
  const number=(key,fallback=0)=>Number.isFinite(parseFloat(style[key]))?parseFloat(style[key]):fallback;
  const select=(id,label,values,current)=>`<label>${label}<select id="${id}">${values.map(([value,text])=>`<option value="${value}" ${value===current?'selected':''}>${text}</option>`).join('')}</select></label>`;
  const input=(id,label,value)=>`<label>${label}<input id="${id}" type="number" min="0" value="${esc(value)}"></label>`;
  const modes=[['fixed','Fixed'],['hug','Hug contents'],['fill','Fill container']];
  content.innerHTML=`<section class="wb-section"><span class="eyebrow">AUTO LAYOUT</span><h3>Flow, spacing and alignment</h3><div class="wb-form">
  ${select('ly-direction','Direction',[['row','Horizontal'],['column','Vertical']],style['flex-direction']||'row')}
  ${select('ly-wrap','Wrap',[['nowrap','No wrap'],['wrap','Wrap']],style['flex-wrap']||'nowrap')}
  ${input('ly-gap','Gap',number('gap',16))}${input('ly-row-gap','Row gap',number('row-gap',number('gap',16)))}${input('ly-column-gap','Column gap',number('column-gap',number('gap',16)))}
  ${select('ly-align','Cross-axis alignment',[['flex-start','Start'],['center','Center'],['flex-end','End'],['stretch','Stretch'],['baseline','Baseline']],style['align-items']||'flex-start')}
  ${select('ly-justify','Main-axis alignment',[['flex-start','Start'],['center','Center'],['flex-end','End'],['space-between','Space between'],['space-around','Space around'],['space-evenly','Space evenly']],style['justify-content']||'flex-start')}
  ${['top','right','bottom','left'].map(side=>input('ly-padding-'+side,'Padding '+side,number('padding-'+side,number('padding',24)))).join('')}
  </div><div class="wb-actions"><button id="ly-apply" class="primary-btn">Apply auto layout</button><button id="ly-remove" class="secondary-btn">Remove auto layout</button></div></section>
  <section class="wb-section"><h3>Resizing</h3><div class="wb-form">${select('ly-width-mode','Width',modes,metadata.sizing?.widthMode||'fixed')}${input('ly-width','Fixed width',number('width',node?.view?.el?.offsetWidth||100))}${select('ly-height-mode','Height',modes,metadata.sizing?.heightMode||'fixed')}${input('ly-height','Fixed height',number('height',node?.view?.el?.offsetHeight||100))}${input('ly-min-width','Minimum width',number('min-width',''))}${input('ly-max-width','Maximum width',number('max-width',''))}${input('ly-min-height','Minimum height',number('min-height',''))}${input('ly-max-height','Maximum height',number('max-height',''))}</div><button id="ly-sizing" class="primary-btn">Apply resizing</button></section>
  <section class="wb-section"><h3>Constraints</h3><p>Keep this layer anchored as its parent frame changes size.</p><div class="wb-form">${select('ly-horizontal','Horizontal',[['left','Left'],['right','Right'],['stretch','Left and right'],['center','Center'],['scale','Scale']],metadata.constraints?.horizontal||'left')}${select('ly-vertical','Vertical',[['top','Top'],['bottom','Bottom'],['stretch','Top and bottom'],['center','Center'],['scale','Scale']],metadata.constraints?.vertical||'top')}</div><button id="ly-constraints" class="primary-btn">Apply constraints</button></section>
  <section class="wb-section"><h3>Layout grid</h3><div class="wb-form">${input('ly-columns','Columns',metadata.grid?.columns||12)}${input('ly-gutter','Gutter',metadata.grid?.gutter??16)}${input('ly-margin','Side margin',metadata.grid?.margin??0)}${input('ly-grid-max-width','Maximum grid width',metadata.grid?.maxWidth??0)}${select('ly-grid-alignment','Alignment',[['stretch','Stretch'],['center','Center']],metadata.grid?.alignment||'stretch')}</div><div class="wb-actions"><button id="ly-grid" class="secondary-btn">Apply columns</button><button id="ly-grid-remove" class="secondary-btn">Remove grid</button></div></section>`;
  const get=id=>content.querySelector('#'+id).value;
  const run=work=>{try{api.commands.execute(work());api.gridOverlay.refresh();api.toast('Layout updated');}catch(error){api.toast(error.message);}};
  content.querySelector('#ly-apply').onclick=()=>{const options={direction:get('ly-direction'),wrap:get('ly-wrap')==='wrap',gap:+get('ly-gap'),rowGap:+get('ly-row-gap'),columnGap:+get('ly-column-gap'),align:get('ly-align'),justify:get('ly-justify')};for(const side of ['top','right','bottom','left'])options['padding'+side[0].toUpperCase()+side.slice(1)]=+get('ly-padding-'+side);run(()=>autoLayoutCommand(node,api.projectState,options));};
  content.querySelector('#ly-remove').onclick=()=>run(()=>removeAutoLayoutCommand(node,api.projectState));
  content.querySelector('#ly-sizing').onclick=()=>{const options={widthMode:get('ly-width-mode'),heightMode:get('ly-height-mode'),width:get('ly-width'),height:get('ly-height'),minWidth:get('ly-min-width'),maxWidth:get('ly-max-width'),minHeight:get('ly-min-height'),maxHeight:get('ly-max-height')};run(()=>sizingCommand(node,api.projectState,options));};
  content.querySelector('#ly-constraints').onclick=()=>{const options={horizontal:get('ly-horizontal'),vertical:get('ly-vertical')};run(()=>constraintCommand(node,api.projectState,options));};
  content.querySelector('#ly-grid').onclick=()=>{const grid={columns:+get('ly-columns'),gutter:+get('ly-gutter'),margin:+get('ly-margin'),maxWidth:+get('ly-grid-max-width'),alignment:get('ly-grid-alignment')};run(()=>gridMetadataCommand(node,api.projectState,grid));};
  content.querySelector('#ly-grid-remove').onclick=()=>run(()=>gridMetadataCommand(node,api.projectState,null));
}
